void twice(int n)
{
    n = n * 2;
}

void twiceRef(int& n)
{
    n = n * 2;
}

int a = 10;
twice(a);

int b = 10;
twiceRef(b);

std::cout << a << " " << b << "\n";

int counter = 0;

void shadow()
{
    int counter = 99;
    std::cout << counter << "\n";
}

int main()
{
    shadow();
    std::cout << counter << "\n";
    return 0;
}

void record()
{
    static int calls = 0;
    int normal = 0;

    calls = calls + 1;
    normal = normal + 1;
    std::cout << calls << " " << normal << "\n";
}

