static bool Overlap(
    double ax, double ay, double aw, double ah,
    double bx, double by, double bw, double bh)
    => ax < bx + bw && ax + aw > bx
    && ay < by + bh && ay + ah > by;

bool apart = Overlap(0, 0, 10, 10, 20, 0, 10, 10);
bool cross = Overlap(0, 0, 10, 10, 5, 5, 10, 10);
