int n = 0, rejected = 0;
foreach (string field in fields)
{
    bool ok = int.TryParse(field, out int value);
    if (ok) { rpm[n] = value; n++; }
    else { rejected++; }
}
Console.WriteLine($"read {n}, rejected {rejected}");

