string captura = "1480,1502,1495,abc,1533,1471,1509,1488";
string[] campos = captura.Split(',');
int[] rpm = new int[campos.Length];
int n = 0, rechazadas = 0;
foreach (string campo in campos)
{
    bool ok = int.TryParse(campo, out int valor);
    if (ok) { rpm[n] = valor; n++; }
    else { rechazadas++; }
}
Console.WriteLine($"leidas {n}, rechazadas {rechazadas}");

// struct Sample { public int Channel, Rpm;
//                 public Status State; }
Sample[] banco = new Sample[n];
int suma = 0, fuera = 0;
for (int i = 0; i < n; i++)
{
    bool malo = rpm[i] < 1480 || rpm[i] > 1520;
    banco[i].Channel = i;
    banco[i].Rpm = rpm[i];
    banco[i].State = malo ? Status.Fault : Status.Ok;
    if (malo) fuera++;
    suma += rpm[i];
}

Console.WriteLine($"fuera de banda {fuera} de {n}");
Console.WriteLine($"media entera {suma / n}");
Console.WriteLine($"media real {(double)suma / n}");
Console.WriteLine($"media :F3 {(double)suma / n:F3}");

int[] ordenadas = new int[n];
Array.Copy(rpm, ordenadas, n);
Array.Sort(ordenadas);

Console.WriteLine("ordenadas:");
Console.WriteLine(string.Join(" ", ordenadas));
int i1495 = Array.BinarySearch(ordenadas, 1495);
int i1500 = Array.BinarySearch(ordenadas, 1500);
Console.WriteLine($"binaria 1495 -> {i1495}");
Console.WriteLine($"binaria 1500 -> {i1500}");

